import{_ as a,c as i,o as s,ae as t}from"./chunks/framework.CHDT0Kbg.js";const f=JSON.parse('{"title":"Politique de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-policy.md","filePath":"fr/guide/privacy-policy.md","lastUpdated":1795170900000}'),o={name:"fr/guide/privacy-policy.md"};function r(n,e,l,c,u,d){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to &quot;Politique de confidentialité&quot;">​</a></h1><p>Ce que Persim collecte et ce qui reste sur votre appareil.</p><h2 id="aucun-compte-aucun-profil-dans-le-cloud" tabindex="-1">Aucun compte, aucun profil dans le cloud <a class="header-anchor" href="#aucun-compte-aucun-profil-dans-le-cloud" aria-label="Permalink to &quot;Aucun compte, aucun profil dans le cloud&quot;">​</a></h2><p>Persim ne demande pas de connexion et ne crée pas de compte en ligne. Historique, favoris, onglets ouverts, téléchargements et cookies sont enregistrés sur votre Mac.</p><h2 id="informations-necessaires-a-l-affichage-des-pages" tabindex="-1">Informations nécessaires à l&#39;affichage des pages <a class="header-anchor" href="#informations-necessaires-a-l-affichage-des-pages" aria-label="Permalink to &quot;Informations nécessaires à l&#39;affichage des pages&quot;">​</a></h2><p>Comme tout navigateur, Persim envoie les adresses visitées aux sites que vous ouvrez. Persim n&#39;envoie pas votre historique de navigation à un serveur.</p><h2 id="fonctions-reseau-que-vous-pouvez-activer" tabindex="-1">Fonctions réseau que vous pouvez activer <a class="header-anchor" href="#fonctions-reseau-que-vous-pouvez-activer" aria-label="Permalink to &quot;Fonctions réseau que vous pouvez activer&quot;">​</a></h2><ul><li>Les abonnements de filtrage mettent à jour leurs listes via le réseau. Si la mise à jour échoue, la liste enregistrée continue de fonctionner.</li><li>Les scripts utilisateur et les fichiers ne sont téléchargés qu&#39;à votre demande.</li><li>Lors de la saisie dans la barre d&#39;adresse, les suggestions proviennent du moteur de recherche choisi.</li></ul><h2 id="autorisations-locales" tabindex="-1">Autorisations locales <a class="header-anchor" href="#autorisations-locales" aria-label="Permalink to &quot;Autorisations locales&quot;">​</a></h2><p>Caméra, micro et accès aux fichiers sont mémorisés par site et modifiables dans les réglages. La localisation et les notifications sont gérées par macOS. Une fenêtre privée (⌘⇧N) ne laisse aucune trace dans l&#39;historique ni la session.</p><h2 id="sites-tiers" tabindex="-1">Sites tiers <a class="header-anchor" href="#sites-tiers" aria-label="Permalink to &quot;Sites tiers&quot;">​</a></h2><p>Les sites que vous visitez sont exploités par d&#39;autres et suivent leurs propres règles de confidentialité. Les pages intégrées de Persim ne vous suivent pas.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions sur la confidentialité : <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',14)])])}const h=a(o,[["render",r]]);export{f as __pageData,h as default};
